/* Pacote do agente (arquivos embutidos) + gerador de .zip. Usado pelo botão "Baixar agente" de automacao-nf.js */
(() => {
  const ARQ = [
  ["LEIA-ME.txt",""],
  ["agente-windows/agente.ps1",""],
  ["agente-windows/descobrir-posicao-do-mouse.bat","QGVjaG8gb2ZmDQpjZCAvZCAiJX5kcDAiDQpwb3dlcnNoZWxsIC1Ob1Byb2ZpbGUgLVNUQSAtRXhlY3V0aW9uUG9saWN5IEJ5cGFzcyAtRmlsZSAiJX5kcDBhZ2VudGUucHMxIiAtUG9zaWNhbw0K"],
  ["agente-windows/iniciar.bat","QGVjaG8gb2ZmDQpjZCAvZCAiJX5kcDAiDQpwb3dlcnNoZWxsIC1Ob1Byb2ZpbGUgLVNUQSAtRXhlY3V0aW9uUG9saWN5IEJ5cGFzcyAtRmlsZSAiJX5kcDBhZ2VudGUucHMxIg0KcGF1c2UNCg=="],
  ["agente-windows/iniciar-como-administrador.bat","QGVjaG8gb2ZmDQpjZCAvZCAiJX5kcDAiDQpwb3dlcnNoZWxsIC1Ob1Byb2ZpbGUgLUNvbW1hbmQgIlN0YXJ0LVByb2Nlc3MgLUZpbGVQYXRoICclfmRwMGluaWNpYXIuYmF0JyAtVmVyYiBSdW5BcyINCg=="],
  ["agente-windows/testar-sem-clicar.bat","QGVjaG8gb2ZmDQpjZCAvZCAiJX5kcDAiDQpwb3dlcnNoZWxsIC1Ob1Byb2ZpbGUgLVNUQSAtRXhlY3V0aW9uUG9saWN5IEJ5cGFzcyAtRmlsZSAiJX5kcDBhZ2VudGUucHMxIiAtVGVzdGFyDQpwYXVzZQ0K"],
  ];
  const T = (() => { const t = new Uint32Array(256); for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; } return t; })();
  const crc32 = u => { let c = 0xFFFFFFFF; for (let i = 0; i < u.length; i++) c = T[(c ^ u[i]) & 255] ^ (c >>> 8); return (c ^ 0xFFFFFFFF) >>> 0; };
  const bytes = b64 => Uint8Array.from(atob(b64), ch => ch.charCodeAt(0));
  CFO.zipNF = () => {
    const enc = new TextEncoder(), parts = [], cen = []; let off = 0;
    ARQ.forEach(([nome, b64]) => {
      const n = enc.encode(nome), d = bytes(b64), crc = crc32(d), sz = d.length;
      const h = new DataView(new ArrayBuffer(30)); h.setUint32(0, 0x04034b50, true); h.setUint16(4, 20, true); h.setUint16(6, 0x0800, true); h.setUint16(12, 0x21, true);
      h.setUint32(14, crc, true); h.setUint32(18, sz, true); h.setUint32(22, sz, true); h.setUint16(26, n.length, true);
      parts.push(new Uint8Array(h.buffer), n, d);
      const c = new DataView(new ArrayBuffer(46)); c.setUint32(0, 0x02014b50, true); c.setUint16(4, 20, true); c.setUint16(6, 20, true); c.setUint16(8, 0x0800, true); c.setUint16(14, 0x21, true);
      c.setUint32(16, crc, true); c.setUint32(20, sz, true); c.setUint32(24, sz, true); c.setUint16(28, n.length, true); c.setUint32(42, off, true);
      cen.push(new Uint8Array(c.buffer), n); off += 30 + n.length + sz;
    });
    const cs = cen.reduce((a, x) => a + x.length, 0), e = new DataView(new ArrayBuffer(22));
    e.setUint32(0, 0x06054b50, true); e.setUint16(8, ARQ.length, true); e.setUint16(10, ARQ.length, true); e.setUint32(12, cs, true); e.setUint32(16, off, true);
    return new Blob([...parts, ...cen, new Uint8Array(e.buffer)], { type: 'application/zip' });
  };
  CFO.baixarAgenteNF = () => {
    const a = document.createElement('a'); a.href = URL.createObjectURL(CFO.zipNF()); a.download = 'agente-cfo.zip';
    document.body.append(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(a.href), 4000);
  };
})();
